199: let AC = null, masterGain = null, noiseBuffer = null;
200: function ensureAudio() {
201:   if (AC) { if (AC.state === 'suspended') AC.resume(); return; }
202:   const C = window.AudioContext || window.webkitAudioContext;
203:   if (!C) return;
204:   AC = new C();
205:   masterGain = AC.createGain();
206:   masterGain.gain.value = profile.muted ? 0 : 0.34;
207:   masterGain.connect(AC.destination);
208:   const len = Math.floor(AC.sampleRate * 1.2);
209:   noiseBuffer = AC.createBuffer(1, len, AC.sampleRate);
210:   const d = noiseBuffer.getChannelData(0);
211:   for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
212: }
213: function setMuted(m, silent) {
214:   profile.muted = !!m;
