221: function blip(freq, dur, type = 'sine', vol = 0.18, slide = 0, delay = 0) {
222:   if (!AC || profile.muted) return;
223:   const t0 = AC.currentTime + delay;
224:   const o = AC.createOscillator(), gn = AC.createGain();
225:   o.type = type;
226:   o.frequency.setValueAtTime(freq, t0);
227:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(35, freq + slide), t0 + dur);
228:   gn.gain.setValueAtTime(0.0001, t0);
229:   gn.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
230:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
231:   o.connect(gn); gn.connect(masterGain);
232:   o.start(t0); o.stop(t0 + dur + 0.03);
233: }
234: function noiseBurst(dur, vol = 0.18, freq = 1100, delay = 0, type = 'bandpass', slideTo) {
235:   if (!AC || profile.muted || !noiseBuffer) return;
236:   const t0 = AC.currentTime + delay;
237:   const src = AC.createBufferSource();
238:   src.buffer = noiseBuffer;
239:   const f = AC.createBiquadFilter();
240:   f.type = type; f.frequency.setValueAtTime(freq, t0);
241:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
242:   const gn = AC.createGain();
243:   gn.gain.setValueAtTime(vol, t0);
244:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
245:   src.connect(f); f.connect(gn); gn.connect(masterGain);
246:   src.start(t0); src.stop(t0 + dur + 0.02);
247: }
