327: function computeLayout() {
328:   const prevW = W, prevH = H, prevFloor = floorY;
329:   W = window.innerWidth;
330:   H = window.innerHeight;
331:   DPR = Math.min(window.devicePixelRatio || 1, 2);
332:   el.canvas.width = Math.round(W * DPR);
333:   el.canvas.height = Math.round(H * DPR);
334:   el.canvas.style.width = W + 'px';
335:   el.canvas.style.height = H + 'px';
336: 
337:   isTouch = window.matchMedia('(pointer: coarse)').matches;
338:   document.body.classList.toggle('touch', isTouch);
339:   S = clamp(Math.sqrt(W * H) / 920, 0.7, 1.25);
340:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
341:   arenaTop = isTouch ? 78 : 96;
342:   floorY = H - apron;
343:   const margin = isTouch ? 14 : 24;
344:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
