346:   skyGrad = ctx.createLinearGradient(0, 0, 0, Math.max(200, floorY));
347:   skyGrad.addColorStop(0, '#3a1e66');
348:   skyGrad.addColorStop(0.38, '#8a3a8d');
349:   skyGrad.addColorStop(0.64, '#f56d73');
350:   skyGrad.addColorStop(0.85, '#ffb35e');
351:   skyGrad.addColorStop(1, '#ffe29a');
352:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
353:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
354:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
355:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
356: 
357:   rebuildDecor();
358:   if (prevW && (prevW !== W || prevH !== H)) {
359:     const sx = W / prevW;
360:     const sy = H / prevFloor;
361:     for (const p of players) {
362:       p.x *= sx;
363:       p.y = prevFloor ? p.y * sy : floorY;
364:       p.y = Math.min(p.y, floorY);
365:     }
366:     for (const b of balls) { b.x *= sx; b.y *= sy; }
367:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
368:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
369:   }
370: }
