372: function generatePlatforms() {
373:   const bw = arena.right - arena.left;
374:   const bh = floorY - arena.top;
375:   const mirror = Math.random() < 0.5;
376:   const w1 = clamp(250 * S, bw * 0.22, bw * 0.34);
377:   const w2 = clamp(215 * S, bw * 0.20, bw * 0.30);
378:   const w3 = clamp(185 * S, bw * 0.17, bw * 0.26);
379: 
380:   // Stepped heights: every step is clearable with a single jump.
381:   const step = Math.min(112 * S, bh * 0.26);
382:   const maxTop = arena.top + Math.max(54 * S, bh * 0.11);
383:   let scale = 1;
384:   if (floorY - step * 3 < maxTop) scale = Math.max(0.35, (floorY - maxTop) / (step * 3));
385:   const y1 = floorY - step * scale;
386:   const y2 = floorY - step * 2 * scale;
387:   const y3 = floorY - step * 3 * scale;
388: 
389:   // Chain the platforms horizontally so each one overlaps the next.
390:   const x1 = arena.left + bw * 0.05;
391:   const x2 = Math.min(x1 + w1 - w2 * 0.34, arena.right - w2 - 10);
392:   const x3 = Math.min(x2 + w2 - w3 * 0.34, arena.right - w3 - 10);
393: 
394:   platforms = [
395:     { x: x1, y: y1, w: w1, h: 24 * S, style: 0 },
396:     { x: x2, y: y2, w: w2, h: 24 * S, style: 1 },
397:     { x: x3, y: y3, w: w3, h: 24 * S, style: 2 },
398:   ];
399: 
400:   if (mirror) {
401:     for (const p of platforms) p.x = arena.left + (arena.right - p.x - p.w);
402:   }
403:   for (const p of platforms) {
404:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
405:     p.y = Math.max(p.y, arena.top + 54 * S);
406:   }
407: }
