243: function drawFace(g, char, o) {
244:   const ey = char.eyeY, gap = char.eyeGap, r = char.eyeR;
245:   const lookX = (o.lookX || 0) * 2.6;
246:   const lookY = (o.lookY || 0) * 2.1;
247:   const ko = o.ko;
248:   const blink = o.blink && !ko;
249:   const excited = o.charging || (o.hurt || 0) > 0;
250: 
251:   if (ko) {
252:     g.strokeStyle = INK; g.lineWidth = 3.4; g.lineCap = 'round';
253:     [-gap, gap].forEach(x => {
254:       g.beginPath();
255:       g.moveTo(x - r * 0.6, ey - r * 0.6); g.lineTo(x + r * 0.6, ey + r * 0.6);
256:       g.moveTo(x + r * 0.6, ey - r * 0.6); g.lineTo(x - r * 0.6, ey + r * 0.6);
257:       g.stroke();
258:     });
259:   } else {
260:     [-gap, gap].forEach((x, i) => {
261:       if (blink) {
262:         g.strokeStyle = INK; g.lineWidth = 3; g.lineCap = 'round';
263:         g.beginPath();
264:         g.moveTo(x - r * 0.8, ey + (i ? -0.5 : 0.5));
265:         g.quadraticCurveTo(x, ey + 2.2, x + r * 0.8, ey + (i ? -0.5 : 0.5));
266:         g.stroke();
267:       } else {
268:         g.beginPath(); g.arc(x, ey, r, 0, TAU);
269:         g.fillStyle = PAPER; g.fill();
270:         g.lineWidth = 3.2; g.strokeStyle = INK; g.stroke();
271:         g.beginPath(); g.arc(x + lookX, ey + lookY, r * 0.44, 0, TAU);
272:         g.fillStyle = INK; g.fill();
273:         g.beginPath(); g.arc(x + lookX - r * 0.18, ey + lookY - r * 0.2, r * 0.13, 0, TAU);
274:         g.fillStyle = '#fff'; g.fill();
275:       }
276:     });
277:     // eyebrows
278:     if (excited) {
279:       g.strokeStyle = INK; g.lineWidth = 3; g.lineCap = 'round';
280:       g.beginPath(); g.moveTo(-gap - r * 0.8, ey - r * 1.5); g.lineTo(-gap + r * 0.6, ey - r * 1.1); g.stroke();
281:       g.beginPath(); g.moveTo(gap + r * 0.8, ey - r * 1.5); g.lineTo(gap - r * 0.6, ey - r * 1.1); g.stroke();
282:     }
283:   }
284: 
285:   // cheeks
286:   if (!ko) {
287:     g.fillStyle = 'rgba(255,93,93,.22)';
288:     g.beginPath(); g.ellipse(-char.bodyW * 0.34, ey + r + 6, 5, 3, 0, 0, TAU); g.fill();
289:     g.beginPath(); g.ellipse(char.bodyW * 0.34, ey + r + 6, 5, 3, 0, 0, TAU); g.fill();
290:   }
291: 
292:   const my = char.mouthY;
293:   if (ko) {
294:     g.beginPath(); g.ellipse(0, my + 3, 6, 7.5, 0, 0, TAU);
295:     g.fillStyle = INK; g.fill();
296:     g.fillStyle = '#ff6f8f';
297:     g.beginPath(); g.ellipse(0, my + 6, 3.4, 2.2, 0, 0, TAU); g.fill();
298:   } else if (excited) {
299:     g.beginPath(); g.ellipse(0, my + 4, 7, 8, 0, 0, TAU);
300:     g.fillStyle = INK; g.fill();
301:     g.beginPath(); g.ellipse(0, my + 7, 4, 3, 0, 0, TAU);
302:     g.fillStyle = '#ff6f8f'; g.fill();
303:   } else {
304:     g.strokeStyle = INK; g.lineWidth = 2.8; g.lineCap = 'round';
305:     g.beginPath();
306:     g.moveTo(-6, my);
307:     g.quadraticCurveTo(0, my + 5, 6, my);
308:     g.stroke();
309:   }
310: }
