341: function drawCharacter(g, char, o) {
342:   const s = o.scale || 1;
343:   g.save();
344:   g.scale(s, s);
345:   const run = o.run || 0;
346:   const phase = o.phase || 0;
347:   const t = o.t || 0;
348:   const bob = o.ko ? 0 : o.onGround
349:     ? (run > 0.06 ? Math.abs(Math.sin(phase)) * 2.4 * run : Math.sin(t * 2.1 + (o.seed || 0)) * 1.4)
350:     : -1.5;
351:   g.translate(0, bob);
352:   if ((o.hurt || 0) > 0) g.rotate(-0.09);
353:   if (o.charging) g.translate(rand(-0.9, 0.9), rand(-0.9, 0.9));
354:   g.scale(o.facing || 1, 1);
355: 
356:   drawLegs(g, char, o);
357:   drawArm(g, char, o, -(o.aim || 1), false);
358:   drawBody(g, char, o);
359:   drawFace(g, char, o);
360:   drawBand(g, char, o);
361:   drawArm(g, char, o, (o.aim || 1), true);
362:   g.restore();
363: }
