365: function drawPlayer(p, t) {
366:   const opp = getOpponent(p);
367:   const color = playerColor(p);
368:   const lookX = opp ? clamp((opp.x - p.x) / (260 * S), -1, 1) * p.facing : 0;
369:   const lookY = opp ? clamp(((opp.y - 42 * S) - (p.y - 52 * S)) / (260 * S), -1, 1) : 0;
370:   const aimSign = opp ? (Math.sign(opp.x - p.x) || 1) : p.facing;
371: 
372:   if ((p.onGround || p.ko) && state !== 'title') {
373:     ctx.beginPath();
374:     ctx.ellipse(p.x, p.y + 2 * S, 26 * S, 6 * S, 0, 0, TAU);
375:     ctx.fillStyle = 'rgba(36,19,53,.22)';
376:     ctx.fill();
377:   }
378: 
379:   ctx.save();
380:   ctx.translate(p.x, p.y);
381:   if (p.invuln > 0 && state === 'play' && Math.floor(p.invuln * 22) % 2 === 0) ctx.globalAlpha = 0.55;
382:   if (p.ko) {
383:     const k = clamp(p.koT / 0.9, 0, 1);
384:     ctx.rotate(k * Math.PI * 0.48 * (p.koDir || 1));
385:   }
386:   drawCharacter(ctx, p.char, {
387:     scale: S,
388:     facing: p.facing,
389:     t, phase: p.runPhase, run: p.onGround ? clamp(Math.abs(p.vx) / (runSpeedFor() || 1), 0, 1) : 0.4,
390:     onGround: p.onGround, vy: p.vy, seed: p.idx * 2.3,
391:     aiming: true, aim: aimSign * p.facing,
392:     charging: p.charging, charge: p.charge,
393:     throwAnim: p.throwAnim, catchAnim: p.catchAnim,
394:     hurt: p.hitstun, ko: p.ko,
395:     lookX, lookY,
396:     blink: p.blink > 0,
397:     color,
398:     showBall: !p.ko && p.throwAnim <= 0 && p.throwCd <= 0,
399:     ballRadius: 7.5 + p.charge * 7,
400:   });
401:   ctx.restore();
402: 
403:   // player ID badge above the head
404:   if (state !== 'title' && state !== 'matchEnd') {
405:     const bw = 19 * S, bh = 16 * S;
406:     const by = p.y - 104 * S;
407:     ctx.save();
408:     ctx.translate(p.x, by);
409:     rr(ctx, -bw / 2, -bh / 2, bw, bh, 7 * S);
410:     ctx.fillStyle = color;
411:     ctx.fill();
412:     ctx.lineWidth = 2.4 * S;
413:     ctx.strokeStyle = INK;
414:     ctx.stroke();
415:     ctx.beginPath();
416:     ctx.moveTo(-3.4 * S, bh / 2 - 1);
417:     ctx.lineTo(0, bh / 2 + 5 * S);
418:     ctx.lineTo(3.4 * S, bh / 2 - 1);
419:     ctx.closePath();
420:     ctx.fillStyle = color; ctx.fill();
421:     ctx.strokeStyle = INK; ctx.lineWidth = 2.2 * S; ctx.stroke();
422:     ctx.font = `${11 * S}px Bungee, sans-serif`;
423:     ctx.textAlign = 'center';
424:     ctx.textBaseline = 'middle';
425:     ctx.fillStyle = p.idx === 0 ? INK : CREAM;
426:     ctx.fillText(String(p.idx + 1), 0, 0.6 * S);
427:     ctx.restore();
428:   }
429:   if (state === 'play' && !p.ko) {
430:     const b = nearbyCatchable(p);
431:     if (b && !p.charging) {
432:       const r = 38 * S + Math.sin(t * 8 + p.idx) * 3 * S;
433:       ctx.beginPath(); ctx.arc(p.x, p.y - 38 * S, r, 0, TAU);
434:       ctx.strokeStyle = withA(color, 0.5);
435:       ctx.lineWidth = 2.5 * S;
436:       ctx.setLineDash([5 * S, 6 * S]);
437:       ctx.stroke();
438:       ctx.setLineDash([]);
439:       ctx.font = `${9 * S}px Bungee, sans-serif`;
440:       ctx.textAlign = 'center';
441:       ctx.fillStyle = withA(CREAM, 0.85);
442:       ctx.fillText('CATCH!', p.x, p.y - 88 * S);
443:     }
444:   }
445: 
446:   // KO stars
447:   if (p.ko) {
448:     for (let i = 0; i < 3; i++) {
449:       const a = t * 3.4 + i * TAU / 3;
450:       const sx = p.x + Math.cos(a) * 22 * S;
451:       const sy = p.y - 82 * S + Math.sin(a) * 9 * S;
452:       ctx.save(); ctx.translate(sx, sy); ctx.rotate(a);
453:       starPath(ctx, 6 * S, 2.6 * S, 5);
454:       ctx.fillStyle = '#ffd23f'; ctx.fill();
455:       ctx.lineWidth = 1.6 * S; ctx.strokeStyle = INK; ctx.stroke();
456:       ctx.restore();
457:     }
458:   }
459: }
