462: function drawSky(t) {
463:   ctx.fillStyle = skyGrad;
464:   ctx.fillRect(0, 0, W, floorY);
465: 
466:   const sunX = W * 0.74, sunY = arena.top + (floorY - arena.top) * 0.22;
467:   const sunR = Math.min(W, H) * 0.072;
468:   ctx.save();
469:   ctx.translate(sunX, sunY);
470:   ctx.rotate(t * 0.018);
471:   ctx.fillStyle = 'rgba(255,236,168,.055)';
472:   for (let i = 0; i < 16; i++) {
473:     const a = i * TAU / 16;
474:     ctx.beginPath();
475:     ctx.moveTo(0, 0);
476:     ctx.arc(0, 0, Math.max(W, H) * 0.7, a, a + 0.1);
477:     ctx.closePath();
478:     ctx.fill();
479:   }
480:   ctx.restore();
481: 
482:   const glow = ctx.createRadialGradient(sunX, sunY, sunR * 0.2, sunX, sunY, sunR * 2.8);
483:   glow.addColorStop(0, 'rgba(255,239,177,.55)');
484:   glow.addColorStop(0.5, 'rgba(255,199,110,.16)');
485:   glow.addColorStop(1, 'rgba(255,160,90,0)');
486:   ctx.fillStyle = glow;
487:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR * 2.8, 0, TAU); ctx.fill();
488:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR, 0, TAU);
489:   ctx.fillStyle = '#ffedb0'; ctx.fill();
490:   ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,244,216,.55)'; ctx.stroke();
491: 
492:   // stars
493:   for (const st of stars) {
494:     const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * st.sp + st.ph));
495:     ctx.beginPath(); ctx.arc(st.x, st.y, st.r, 0, TAU);
496:     ctx.fillStyle = `rgba(255,244,216,${tw * 0.65})`; ctx.fill();
497:   }
498: 
499:   // clouds
500:   ctx.fillStyle = 'rgba(255,220,190,.18)';
501:   for (const c of clouds) {
502:     const x = ((c.x + t * c.sp + 160) % (W + 320)) - 160;
503:     const y = c.y + Math.sin(t * 0.4 + c.ph) * 3;
504:     ctx.globalAlpha = c.a;
505:     ctx.beginPath();
506:     ctx.ellipse(x, y, 46 * c.s, 15 * c.s, 0, 0, TAU);
507:     ctx.ellipse(x + 34 * c.s, y - 8 * c.s, 30 * c.s, 17 * c.s, 0, 0, TAU);
508:     ctx.ellipse(x - 36 * c.s, y - 4 * c.s, 26 * c.s, 13 * c.s, 0, 0, TAU);
509:     ctx.fill();
510:     ctx.globalAlpha = 1;
511:   }
512: }
