101: function collideBallRect(b, pl) {
102:   const nx = clamp(b.x, pl.x, pl.x + pl.w);
103:   const ny = clamp(b.y, pl.y, pl.y + pl.h);
104:   const dx = b.x - nx, dy = b.y - ny;
105:   const d2 = dx * dx + dy * dy;
106:   if (d2 > b.r * b.r) return false;
107:   let nX, nY;
108:   const d = Math.sqrt(d2);
109:   if (d < 0.001) {
110:     const l = b.x - pl.x, r = pl.x + pl.w - b.x, t = b.y - pl.y, bo = pl.y + pl.h - b.y;
111:     const m = Math.min(l, r, t, bo);
112:     if (m === l) { nX = -1; nY = 0; b.x = pl.x - b.r; }
113:     else if (m === r) { nX = 1; nY = 0; b.x = pl.x + pl.w + b.r; }
114:     else if (m === t) { nX = 0; nY = -1; b.y = pl.y - b.r; }
115:     else { nX = 0; nY = 1; b.y = pl.y + pl.h + b.r; }
116:   } else {
117:     nX = dx / d; nY = dy / d;
118:     b.x = nx + nX * b.r;
119:     b.y = ny + nY * b.r;
120:   }
121:   const dot = b.vx * nX + b.vy * nY;
122:   if (dot >= 0) return false;
123:   b.vx -= (1 + b.rest) * dot * nX;
124:   b.vy -= (1 + b.rest) * dot * nY;
125:   b.vx *= 0.995;
126:   b.vy *= 0.995;
127:   b.spin += rand(-5, 5);
128:   return true;
129: }
