239: /* ---------------- touch pads ---------------- */
240: .touch{position:absolute;inset:0;z-index:30;pointer-events:none}
241: .touch .pad{
242:   --btn:clamp(44px,5.6vh,56px);
243:   position:absolute;bottom:max(7px,env(safe-area-inset-bottom));
244:   display:grid;grid-template-columns:var(--btn) var(--btn) var(--btn);
245:   grid-template-rows:var(--btn) var(--btn);gap:6px;pointer-events:none;
246: }
247: .touch .pad.p1{left:max(9px,env(safe-area-inset-left))}
248: .touch .pad.p2{right:max(9px,env(safe-area-inset-right))}
249: .tbtn{
250:   pointer-events:auto;touch-action:none;appearance:none;
251:   border:2.5px solid var(--ink);border-radius:15px;background:rgba(255,244,216,.9);
252:   color:var(--ink);font-family:"Bungee",sans-serif;font-size:13px;line-height:1;
253:   box-shadow:0 4px 0 var(--ink),inset 0 -3px 0 rgba(0,0,0,.08);
