265: .pause-mini{
266:   position:absolute;left:50%;bottom:max(8px,env(safe-area-inset-bottom));transform:translateX(-50%);
267:   width:36px;height:31px;padding:0;border-radius:9px;font-size:11px;letter-spacing:.05em;
268:   pointer-events:auto;background:rgba(255,244,216,.9);z-index:31;
